import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"WhatsApp Cloud — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"WhatsApp Cloud — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/whatsapp-cloud-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"WhatsApp Cloud — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/whatsapp-cloud-production-readiness"}]]},"headers":[],"relativePath":"deployment/whatsapp-cloud-production-readiness.md","filePath":"deployment/whatsapp-cloud-production-readiness.md","lastUpdated":1787438330000}'),r={name:"deployment/whatsapp-cloud-production-readiness.md"};function s(n,t,i,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="whatsapp-cloud-—-production-readiness-audit" tabindex="-1">WhatsApp Cloud — Production Readiness Audit <a class="header-anchor" href="#whatsapp-cloud-—-production-readiness-audit" aria-label="Permalink to &quot;WhatsApp Cloud — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-22</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — post-MVP polish (1.1–1.3) engineering residuals closed; complete ops pre-flight + Phase 1–3 staging smoke before production opt-in traffic</td></tr><tr><td><strong>Scope</strong></td><td>Billable Marketplace module <code>whatsapp-cloud</code> catalog <strong>1.3.0</strong> (CRM) + Automation catalog <strong>1.1.0</strong> (WA trigger/action)</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/whatsapp-cloud-post-mvp-polish</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./whatsapp-cloud">WhatsApp Cloud deployment</a> · <a href="/developer-guide/whatsapp-cloud-integration">Developer guide</a> · <a href="/user-guide/whatsapp-cloud">User guide</a> · <a href="/api/tenant-v1-whatsapp-cloud">API</a> · <a href="/developer-guide/automation">Automation</a></td></tr></tbody></table><p><strong>PRs:</strong> Backend <a href="https://github.com/DiligentCreators/SaaS-Backend/pull/141" target="_blank" rel="noreferrer">#141</a> · Frontend <a href="https://github.com/DiligentCreators/SaaS-Frontend/pull/134" target="_blank" rel="noreferrer">#134</a> · Docs <a href="https://github.com/DiligentCreators/SaaS-Docs/pull/161" target="_blank" rel="noreferrer">#161</a></p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>WhatsApp Cloud remains a <strong>billable</strong> CRM Marketplace SKU (<code>$29/mo</code>, <code>$290/yr</code>), <strong>not</strong> default-included.</p><table tabindex="0"><thead><tr><th>Catalog</th><th>Version</th><th>Surface</th></tr></thead><tbody><tr><td><code>whatsapp-cloud</code></td><td><strong>1.3.0</strong></td><td>MVP inbox + Lead Source (1.1) + Automation hooks (1.2) + media (1.3)</td></tr><tr><td><code>automation</code></td><td><strong>1.1.0</strong></td><td><code>whatsapp.message_received</code> trigger + <code>send_whatsapp_template</code> action</td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> for merge after CI green. Ops must still complete migrations through media bump, Forge queues (<code>whatsapp-inbound</code>, <code>whatsapp-outbound</code>, <code>automations</code>), Meta credentials with <strong><code>META_HTTP_FAKE</code> unset</strong>, and staging smoke for Phases 1–3 before customer traffic.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog migrate-only bumps to WA <strong>1.3.0</strong> / automation <strong>1.1.0</strong></td><td><strong>Pass</strong></td></tr><tr><td>CatalogSeeder seed versions align with migrate bumps</td><td><strong>Pass</strong></td></tr><tr><td>Lead Source opt-in (<code>auto_create_leads</code> default false)</td><td><strong>Pass</strong></td></tr><tr><td>Automation via <code>IntegrationEventDispatcher</code></td><td><strong>Pass</strong></td></tr><tr><td>Media attachments + soft Storage quota</td><td><strong>Pass</strong></td></tr><tr><td>Inbound MIME allowlist + declared-size quota check before Graph download</td><td><strong>Pass</strong></td></tr><tr><td>Attachment download scoped to conversation (IDOR denied)</td><td><strong>Pass</strong></td></tr><tr><td>Webhook verify + HMAC; CSRF exempt <code>webhooks/whatsapp/*</code></td><td><strong>Pass</strong></td></tr><tr><td>Encrypted tenant tokens; OAuth soft-delete restore</td><td><strong>Pass</strong></td></tr><tr><td><code>META_HTTP_FAKE</code> never active in production</td><td><strong>Pass</strong></td></tr><tr><td>Pest WhatsApp suite (module + media + automation)</td><td><strong>Pass</strong> (<strong>30+</strong>)</td></tr><tr><td>Playwright WhatsApp shared session + Automation WA trigger</td><td><strong>Pass</strong></td></tr><tr><td>Docs hubs + this readiness page current for 1.3.0</td><td><strong>Pass</strong></td></tr></tbody></table><hr><h2 id="locked-decision-matrix" tabindex="-1">Locked-decision matrix <a class="header-anchor" href="#locked-decision-matrix" aria-label="Permalink to &quot;Locked-decision matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Backend</th><th>Frontend</th><th>Docs</th></tr></thead><tbody><tr><td>Packaging billable <code>whatsapp-cloud</code></td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Soft Lead link (no hard module dep)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Keep <code>wa.me</code> Communication Templates fallback</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Opt-in Lead Source auto-create (default <strong>off</strong>)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Automation WA trigger + template action</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Media image/document/audio/video</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Interactive buttons/lists / alternate BSPs / AI WA</td><td>Deferred</td><td>Deferred</td><td>Deferred</td></tr></tbody></table><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_08_16_100005</code> / <code>100006</code></td><td>Register WA <strong>1.0.0</strong> + permissions</td></tr><tr><td><code>2026_08_21_234243</code></td><td><code>auto_create_leads</code>, <code>default_lead_source</code></td></tr><tr><td><code>2026_08_21_234245</code></td><td>WA <strong>1.0.0 → 1.1.0</strong></td></tr><tr><td><code>2026_08_21_235205</code></td><td>Automation <strong>1.0.0 → 1.1.0</strong>, WA <strong>1.1.0 → 1.2.0</strong></td></tr><tr><td><code>2026_08_21_235553</code></td><td><code>whatsapp_message_attachments</code></td></tr><tr><td><code>2026_08_21_235556</code></td><td>WA <strong>1.2.0 → 1.3.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. <code>CatalogSeeder</code> now seeds WA <strong>1.3.0</strong> / automation <strong>1.1.0</strong> for local fresh seeds.</p><hr><h2 id="findings-2026-08-22-audit-remediations" tabindex="-1">Findings (2026-08-22 audit remediations) <a class="header-anchor" href="#findings-2026-08-22-audit-remediations" aria-label="Permalink to &quot;Findings (2026-08-22 audit remediations)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>D1</td><td>High</td><td>Readiness/deploy docs claimed 1.0.0 + Deferred polish</td><td>Docs refreshed</td></tr><tr><td>D2</td><td>Medium</td><td>Developer guide listed polish as deferred</td><td>Corrected</td></tr><tr><td>F12</td><td>High</td><td>Soft-deleted connection blocked OAuth reconnect</td><td><code>withTrashed</code> + restore; Pest</td></tr><tr><td>E1</td><td>Low</td><td>Inbound MIME / download-before-quota</td><td><code>WhatsAppMediaRules</code> allowlist; declared <code>file_size</code> + max 16 MiB checked <strong>before</strong> Graph binary download</td></tr><tr><td>E2</td><td>Low</td><td>Thin IDOR/quota/Automation WA UI coverage</td><td>Pest IDOR + mime + quota; Playwright Automation WA trigger selectable</td></tr><tr><td>E3</td><td>Low</td><td>CatalogSeeder WA version drift</td><td>Seeder → WA <strong>1.3.0</strong>, automation <strong>1.1.0</strong></td></tr></tbody></table><h3 id="ops-not-code-blockers" tabindex="-1">Ops (not code blockers) <a class="header-anchor" href="#ops-not-code-blockers" aria-label="Permalink to &quot;Ops (not code blockers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Owner</th></tr></thead><tbody><tr><td>O1</td><td>Medium</td><td>Companion CI Quality Gates on polish PRs</td><td>Eng</td></tr><tr><td>O2</td><td>Medium</td><td>Forge: <code>whatsapp-inbound</code>, <code>whatsapp-outbound</code>, <code>automations</code></td><td>Ops</td></tr><tr><td>O3</td><td>Medium</td><td>Meta App Review + production URLs; <code>META_HTTP_FAKE</code> unset</td><td>Ops</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — migrate through <code>2026_08_21_235556</code>; workers include WhatsApp + <code>automations</code> queues</li><li><strong>Frontend</strong> — SPA with Lead Source settings + media attach</li><li><strong>Docs</strong> — this readiness page + deploy/user/dev/API</li><li>Staging smoke (Phases 1–3) before production traffic</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations through <code>2026_08_21_235556</code> (attachments + catalog <strong>1.3.0</strong>)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog <code>whatsapp-cloud</code> = <strong>1.3.0</strong>; <code>automation</code> = <strong>1.1.0</strong> where WA Automation is used</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Queue workers: <strong><code>whatsapp-inbound</code></strong>, <strong><code>whatsapp-outbound</code></strong>, <strong><code>automations</code></strong></td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Meta WhatsApp product; webhook <code>{APP_URL}/webhooks/whatsapp/cloud</code>; OAuth <code>{APP_URL}/api/oauth/whatsapp/cloud/callback</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Central/env Meta secrets; <strong><code>META_HTTP_FAKE</code> unset</strong>; stable <code>APP_KEY</code>; <code>FRONTEND_URL</code> matches SPA origin</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Marketplace purchase → pending → payment/<code>activate</code> before inbox entitlements</td><td>Ops</td><td>☐</td></tr><tr><td>7</td><td>Pest WhatsApp directory green</td><td>Eng</td><td>☐</td></tr><tr><td>8</td><td>Playwright <code>test:e2e:whatsapp-cloud</code> + Automation WA trigger case green</td><td>QA</td><td>☐</td></tr><tr><td>9</td><td>Storage entitled for media workspaces; Leads entitled for Lead Source / soft-link</td><td>Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><h3 id="mvp-baseline" tabindex="-1">MVP baseline <a class="header-anchor" href="#mvp-baseline" aria-label="Permalink to &quot;MVP baseline&quot;">​</a></h3><ol><li>Marketplace → install <strong>WhatsApp Cloud</strong></li><li>Staff with <code>view</code>+<code>send</code> sees inbox when connected</li><li>Admin <strong>Connect</strong> → OAuth → select WABA → select phone</li><li>Inbound → reply inside 24h; template outside 24h</li><li>Soft-link / unlink Lead; Lead detail <strong>Inbox</strong> filter; <code>wa.me</code> when Comm Templates entitled</li><li>needs_reauth banner + notification</li><li><strong>Disconnect</strong> → history retained; phone id reclaimable</li></ol><h3 id="phase-1-—-lead-source-1-1-0" tabindex="-1">Phase 1 — Lead Source (1.1.0) <a class="header-anchor" href="#phase-1-—-lead-source-1-1-0" aria-label="Permalink to &quot;Phase 1 — Lead Source (1.1.0)&quot;">​</a></h3><ol start="8"><li>Enable <strong>Auto-create leads</strong>; save default source label; inbound from unknown number creates/links Lead</li><li>Disable auto-create → no Lead write</li></ol><h3 id="phase-2-—-automation-1-2-0-automation-1-1-0" tabindex="-1">Phase 2 — Automation (1.2.0 / automation 1.1.0) <a class="header-anchor" href="#phase-2-—-automation-1-2-0-automation-1-1-0" aria-label="Permalink to &quot;Phase 2 — Automation (1.2.0 / automation 1.1.0)&quot;">​</a></h3><ol start="10"><li>Workflow: trigger <code>whatsapp.message_received</code> → observe run</li><li>Action <code>send_whatsapp_template</code> resolves conversation; blocked if WhatsApp not entitled</li></ol><h3 id="phase-3-—-media-1-3-0" tabindex="-1">Phase 3 — Media (1.3.0) <a class="header-anchor" href="#phase-3-—-media-1-3-0" aria-label="Permalink to &quot;Phase 3 — Media (1.3.0)&quot;">​</a></h3><ol start="12"><li>Inbound image/document → <code>DownloadWhatsAppMediaJob</code> → downloadable in inbox</li><li>Outbound attach inside 24h; outside 24h media rejected</li><li>Disallowed MIME / over-quota inbound does not store attachment</li><li>Storage used bytes include WhatsApp attachments</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace uninstall / cancel</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back WhatsApp migrations without a data plan</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Queues: <code>whatsapp-inbound</code> (webhook + media download), <code>whatsapp-outbound</code>, <code>automations</code> — <code>php artisan queue:failed</code></li><li>Connection <code>status</code> / <code>last_error</code> / phone <code>health</code></li><li>Notification types: <code>whatsapp.inbound</code>, <code>whatsapp.send_failed</code>, <code>whatsapp.needs_reauth</code></li><li>Storage usage / soft quota denials on media</li><li>Meta Graph 4xx/5xx in application logs</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> <strong>Go</strong> — merge companions after CI green; complete staging smoke (Phases 1–3) and Forge queue/Meta setup before production opt-in traffic.</p>',48)])])}const g=e(r,[["render",s]]);export{u as __pageData,g as default};
